sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var ga=new GlideAjax("x_1916809_ai_for_0.Device_Details");
   ga.addParam("sysparm_name","getDetails");
   ga.addParam("sysparm_getDeviceId",g_form.getValue("u_device_name"));
   ga.getXMLAnswer(getdata);
   function getdata(response){
        var ans=JSON.parse(response);
		g_form.setValue("u_model",ans.model);
		g_form.setValue("u_device_description",ans.description);
		g_form.setValue("u_price",ans.price);
		g_form.setValue("u_warrenty_expiration",ans.warranty);
   }

}
